    "/api/v1/users": {
      "get": {
        "operationId": "getUsers",
        "summary": "List user profiles the caller may see",
        "description": "How much of the user table a caller may see, which is a different answer for\nan ordinary member than for whoever administers the instance:\n  - `?id=<userId>`     → single minimal profile (id, name, image)\n  - `?spaceId=<id>`    → members of a space the caller belongs to, the same\n                         minimal profiles\n  - unscoped           → the register: accounts with their email, group claim\n                         and join date, for an instance admin — and an empty\n                         one for anyone else. `{ users, limit, nextCursor }`,\n                         newest first, cursor-paged like every other listing.\n\nThe scoped forms are deliberately narrow, and stay so: they are what any\nsigned-in account may ask, and an unscoped listing there would dump the table\nand every address in it. Unscoped is the register, and what makes it\nanswerable is that an instance admin is owner on every space that exists — it\nshows them nothing they could not read a space at a time. Anyone else gets an\nempty array, not a refusal: this is a listing of what the caller may see, and\nfor them that is nothing. Inviting people is still done by email through the\npermissions endpoint; nobody needs the register for that.\n\nA parameter this route does not know is a `400`, whichever form it would\notherwise have selected: the scopes are how a caller says what it wants, and a\nmisspelled one must not silently become a different question.",
        "tags": [
          "Users"
        ],
        "parameters": [
          {
            "name": "limit",
            "in": "query",
            "required": false,
            "description": "Page size.",
            "schema": {
              "type": "integer"
            }
          },
          {
            "name": "cursor",
            "in": "query",
            "required": false,
            "description": "Opaque cursor from the previous page's `nextCursor`.",
            "schema": {
              "type": "string"
            }
          },
          {
            "name": "id",
            "in": "query",
            "required": false,
            "description": "Read a single profile by user id.",
            "schema": {
              "type": "string"
            }
          },
          {
            "name": "spaceId",
            "in": "query",
            "required": false,
            "description": "Members of a space the caller belongs to.",
            "schema": {
              "type": "string"
            }
          }
        ],
        "responses": {
          "200": {
            "description": "Success",
            "content": {
              "application/json": {
                "schema": {}
              }
            }
          },
          "400": {
            "$ref": "#/components/responses/BadRequest"
          },
          "401": {
            "$ref": "#/components/responses/Unauthorized"
          },
          "403": {
            "$ref": "#/components/responses/Forbidden"
          },
          "429": {
            "$ref": "#/components/responses/RateLimited"
          },
          "500": {
            "$ref": "#/components/responses/ServerError"
          }
        },
        "security": [
          {
            "accessToken": []
          },
          {
            "sessionCookie": []
          }
        ]
      }
    },
